48	 * @author Vitaliy Fedoriv
49	 */
50	
51	@RestController
52	@CrossOrigin(exposedHeaders = "errors, content-type")
53	@RequestMapping("/api")
54	public class OwnerRestControllerV1 implements OwnersApi {
55	
56	    private final ClinicService clinicService;
57	
58	    private final OwnerMapper ownerMapper;
59	
60	    private final PetMapper petMapper;
61	
62	    private final VisitMapper visitMapper;
63	
64	    public OwnerRestControllerV1(ClinicService clinicService,
65	                                 OwnerMapper ownerMapper,
66	                                 PetMapper petMapper,
67	                                 VisitMapper visitMapper) {
68	        this.clinicService = clinicService;
69	        this.ownerMapper = ownerMapper;
70	        this.petMapper = petMapper;
71	        this.visitMapper = visitMapper;
72	    }
73	
74	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
75	    @Override
76	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
77	        Collection<Owner> owners;
78	        if (lastName != null) {
79	            owners = this.clinicService.findOwnerByLastName(lastName);
80	        } else {
81	            owners = this.clinicService.findAllOwners();
82	        }
83	        if (owners.isEmpty()) {
84	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
85	        }
86	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
87	    }
88	
89	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
90	    @Override
91	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
92	        Owner owner = this.clinicService.findOwnerById(ownerId);
93	        if (owner == null) {
94	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
95	        }
96	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
97	    }
98	
99	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
100	    @Override
101	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
102	        HttpHeaders headers = new HttpHeaders();
103	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
104	        Collection<Owner> existingOwners = this.clinicService.findAllOwners();
105	        if (DailyRegistrationLimit.isReached(existingOwners)) {
106	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
107	        }
108	        HouseholdDuplicates.assignHousehold(owner, existingOwners, ownerFieldsDto.getSharesHousehold());
109	        if (IdentityKey.isDuplicate(owner, existingOwners)
110	            || HouseholdDuplicates.isRejectedDuplicate(owner, existingOwners, ownerFieldsDto.getSharesHousehold())
111	            || CityCapacity.isAtCapacity(owner, existingOwners)) {
112	            return new ResponseEntity<>(HttpStatus.CONFLICT);
113	        }
114	        owner.setPossibleDuplicateOf(
115	            PossibleDuplicates.matchId(owner, existingOwners, ownerFieldsDto.getSharesHousehold()));
116	        owner.setNamesakeCount(Namesakes.count(owner, existingOwners));
117	        owner.setCustomerCode(CustomerCodes.build(owner, existingOwners));
118	        this.clinicService.saveOwner(owner);
119	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
120	        ownerDto.setBulkSignupWarning(BulkSignupWarning.isTriggered(existingOwners));
121	        headers.setLocation(UriComponentsBuilder.newInstance()
122	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
123	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
124	    }
125	
126	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
127	    @Override
128	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
129	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
130	        if (currentOwner == null) {
131	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
132	        }
133	        currentOwner.setAddress(ownerFieldsDto.getAddress());
134	        currentOwner.setCity(ownerFieldsDto.getCity());
